学习记录 第1天 - P1216 数字三角形 body{max-width:800px;margin:0 auto;padding:2rem;background:#f8f9fa;font-family:微软雅黑,sans-serif;}
    .card{background:#fff;padding:2rem;border-radius:10px;box-shadow:0 0 8px #eee;}
    h1{color:#222;border-left:5px solid #007bff;padding-left:12px;font-size:22px;}
    h3{margin-top:1.8rem;color:#333;}
    p{line-height:1.7;color:#444;}
    ul{line-height:1.8;color:#444;}
    pre{background:#2f2f2f;color:#eee;padding:15px;border-radius:8px;overflow-x:auto;}
    .tip{background:#eef6ff;padding:12px;border-left:4px solid #007bff;border-radius:6px;margin:1rem 0;}
    img{max-width:100%;border-radius:6px;margin:10px 0;}
    a{color:#007bff;text-decoration:none;}
    a:hover{text-decoration:underline;} 刷题记录：洛谷 P1216 数字三角形 日期：2025-05-05 题型：动态规划 DP 入门题 难度：普及/提高− 题目大意 给定一个数字三角形，从顶部出发，每一步只能向左下或右下走，求走到最底层路径上数字和的最大值。 解题思路 经典入门 DP 模型 首先，这道题如果使用暴力枚举，那么假如层数很大，直接指数爆炸.
            因此看每一步的选择，都由子问题组成，走到某个点只能来自他的上一层某两个点，会发现很多不一样的路径都会经过同一个点，
            那么把每个点的最优值（到达每一行的最大值）存储下来，下次直接用存档，这种想法可以使用dp这种大问题拆成小问题的算法解决最值和方案数。
            dp特征：最优子结构,无后效性,每一步的规则（状态）固定 可以从上往下递推，也可以从下往上倒推 状态定义：dp[i][j] 表示走到第 i 行第 j 列的最大和 每个位置只能由上方左上、上方正上转移而来 从上到下dp代码展示 #include <iostream>
#include <algorithm>
using namespace std;

const int MAXN=1005;
int a[MAXN][MAXN];//存原始三角塔
int dp[MAXN][MAXN];

int main(){
    int r;
    cin>>r;
    for(int i=1;i<=r;i++){//读入每一行
        for(int j=1;j<=i;j++){//第i行有i个数
            cin>>a[i][j];
        }
    }
    dp[1][1]=a[1][1];//初始化起点
    for(int i=2;i<=r;i++){//处理边界
        dp[i][1]=dp[i-1][1]+a[i][1];//每行最左的
        dp[i][i]=dp[i-1][i-1]+a[i][i];//每行最右
    }
    for(int i=3;i<=r;i++){//开始有中间数值处理
        for(int j=2;j<i;j++){
            dp[i][j]=a[i][j]+max(dp[i-1][j-1],dp[i-1][j]);//存档+max
        }
    }
    int result =0;
    for(int j=1;j<=r;j++){//遍历最后一行，找最大值
        result=max(result,dp[r][j]);
    }
    cout<<result<<endl;
    return 0;
} 从下到上dp代码展示 #include <iostream>
#include <algorithm>
using namespace std;
const int MAXN=1005;
int a[MAXN][MAXN];
int dp[MAXN][MAXN];

int main()
{
    int n;
    cin>>n;
    for(int i=1;i<=n;i++)
        for(int j=1;j<=i;j++)
            cin>>a[i][j];
    for(int j=1;j<=n;j++)//初始化最后一行
        dp[n][j]=a[n][j];

    for(int i=n-1;i>=1;i--)//从下向上，无需考虑边界问题
        for(int j=1;j<=i;j++)
            dp[i][j]=a[i][j]+max(dp[i+1][j],dp[i+1][j+1]);

    cout<<dp[1][1]<<endl;
    return 0;
} 刷题记录2：力扣153 旋转数组找最小值 题型：二分查找变形 难度：中等 题目大意 给出升序的一个数组，找出其围绕中位旋转某次后的最小值 解题思路 题目重点：无重复，升序，找最小值，考虑普通二分，但没有固定target，就做细节处变形 原数组整体升序，且旋转后拆成两段各自升序的子数组，最小值就是两段的分界点。 二分不找固定 target，用中间位置 mid 和 右边界 r 比较 若 nums[mid] > nums[r]：最小值一定在右半区间，令l=mid+1 若 nums[mid] < nums[r]：最小值在左半区间或mid本身，令r=mid 循环条件l < r，结束时l与r重合，指向最小值下标 防止re：mid用l+(r-l)/2防止溢出 #include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);//关闭同步，加速 cin/cout
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> nums(n);
    for (int i = 0; i <n;++i){
        cin >> nums[i];
}
    int l=0, r=n-1;
    while (l < r) {
        int mid=l+(r-l)/2; //防溢出
        if (nums[mid] > nums[r])//最小值在右
            l = mid+1;
        else
            r = mid;
    }

    cout << nums[l] << endl;
    return 0;
} 今日总结 掌握了数字三角形基础DP,二分无target变形思路 题1理解了从下往上递推更简洁，不用处理边界。题2只与右边界比才能处理两种情况,不断收敛区间找最小 熟悉了二维数组DP的写法，回忆二分法模板与用法细节 明天计划学习dp系统课+算法题，数据库原理，单词打卡 ← 返回我的学习主页

