目标是在不越界、不超过 5000 步的前提下， 到达 Mandy 的位置，并且手中数字恰好等于目标值 ，
同时输出完整移动路径。 💡 官方题解核心思想 ❌ 不能直接 BFS (x, y, value)，状态空间会爆炸 ✅ 官方解法将问题 拆成两部分 ① 坐标路径：先走到 Mandy 位置 ② 数字变化：在不影响坐标的前提下调整数字 关键转化： 左右移动只影响 +1 / -1 上下移动影响 *2 / /2 可以通过「来回走」在原地完成数字调整 🧠 解题步骤（官方） Step 1：用 BFS 只在 二维坐标 上找最短路 Step 2：根据当前数字 → 目标数字，反向构造操作序列 Step 3：把数字操作映射成合法的移动（原地往返） Step 4：拼接路径，总步数 ≤ 5000 ⚙️ AC 代码（官方思路实现） #include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int sx,sy,tx,ty;
    long long v0,v1;
    cin>>sx>>sy>>v0;
    cin>>tx>>ty>>v1;

    // 1️⃣ 坐标 BFS
    const int MAX=2000;
    vector<vector<int>> vis(MAX+1,vector<int>(MAX+1,-1));
    queue<pair<int,int>> q;
    q.push({sx,sy});
    vis[sx][sy]=0;

    int dx[4]={1,-1,0,0};
    int dy[4]={0,0,1,-1};
    char dc[4]={'D','A','W','S'};

    vector<vector<char>> pre(MAX+1,vector<char>(MAX+1));

    while(!q.empty()){
        auto [x,y]=q.front();q.pop();
        if(x==tx && y==ty) break;
        for(int i=0;i<4;i++){
            int nx=x+dx[i],ny=y+dy[i];
            if(nx<0||ny<0||nx>MAX||ny>MAX) continue;
            if(vis[nx][ny]!=-1) continue;
            vis[nx][ny]=vis[x][y]+1;
            pre[nx][ny]=dc[i];
            q.push({nx,ny});
        }
    }

    // 回溯坐标路径
    string path="";
    int x=tx,y=ty;
    while(x!=sx||y!=sy){
        char c=pre[x][y];
        path.push_back(c);
        if(c=='D') x--;
        if(c=='A') x++;
        if(c=='W') y--;
        if(c=='S') y++;
    }
    reverse(path.begin(),path.end());

    // 2️⃣ 数字调整（反向）
    string ops="";
    while(v1!=v0){
        if(v1>v0){
            if(v1%2==0){ v1/=2; ops.push_back('W'); }
            else{ v1--; ops.push_back('D'); }
        }else{
            v1++; ops.push_back('A');
        }
    }
    reverse(ops.begin(),ops.end());

    // 3️⃣ 输出
    cout<<path<<ops<<'\n';
    return 0;
} 📎 易错点总结 直接 BFS value 一定 TLE / MLE 数字变化必须“原地完成” 注意反向构造再 reverse 📚 今日总结 学会识别「状态爆炸」的 BFS 陷阱 理解官方解法为何要拆问题 构造题比暴搜更重要的是 思路设计

